package br.com.admeclesial.domain.pessoa; import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID; @Entity @Table(name="relacionamento_pessoa",schema="adm_eclesial") public class RelacionamentoPessoa { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="pessoa_origem_id",nullable=false) Long pessoaOrigemId; @Column(name="pessoa_destino_id",nullable=false) Long pessoaDestinoId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) TipoRelacionamentoPessoa tipoRelacionamento; @Column(name="data_inicio",nullable=false) LocalDate dataInicio; @Column(name="data_fim") LocalDate dataFim; @Column(columnDefinition="text") String observacao; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;}public UUID getUuid(){return uuid;}public Long getPessoaOrigemId(){return pessoaOrigemId;}public Long getPessoaDestinoId(){return pessoaDestinoId;}public TipoRelacionamentoPessoa getTipoRelacionamento(){return tipoRelacionamento;}public LocalDate getDataInicio(){return dataInicio;}public LocalDate getDataFim(){return dataFim;}public String getObservacao(){return observacao;}public void setPessoaOrigemId(Long v){pessoaOrigemId=v;}public void setPessoaDestinoId(Long v){pessoaDestinoId=v;}public void setTipoRelacionamento(TipoRelacionamentoPessoa v){tipoRelacionamento=v;}public void setDataInicio(LocalDate v){dataInicio=v;}public void setDataFim(LocalDate v){dataFim=v;}public void setObservacao(String v){observacao=v;} }